{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 동물복지지원센터에서 반려동물 사망 관련 도움을 받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 동물복지지원센터는 반려동물 상실 증후군의 예방 및 완화 지원을 수행할 수 있다. 반려동물 상실 증후군은 반려동물을 기르던 사람이 그 반려동물의 죽음이나 실종 등으로 과도한 우울감이나 인지감정의 부정적 변화 등의 정신적 고통을 겪는 경우를 말한다. 따라서 키우던 반려동물이 죽어 정신적 고통을 겪는 경우 동물복지지원센터에서 관련 도움을 받을 수 있다.",
          "b_ids": "동물보호:제24조제2항제9호의2, 동물보호:제2조제6호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
